import type { Locale } from "@/content/product";

type Localized = Record<Locale, string>;

export type ModuleCapability = {
  id: string;
  title: Localized;
  summary: Localized;
  detail: Localized;
  benefit: Localized;
};

export type ModuleQuestion = {
  question: Localized;
  answer: Localized;
};

export type ModuleConnection = {
  featureId: string;
  description: Localized;
};

export type ModulePageContent = {
  headline: Localized;
  introduction: Localized;
  capabilitiesHeading: Localized;
  capabilitiesIntro: Localized;
  capabilities: ModuleCapability[];
  workflow?: {
    heading: Localized;
    introduction: Localized;
    steps: Localized[];
  };
  intelligenceHeading: Localized;
  questions: ModuleQuestion[];
  connectionsHeading: Localized;
  connections: ModuleConnection[];
  governanceHeading: Localized;
  governance: Localized;
  editionHeading: Localized;
  edition: Localized;
};

export const productPageSlugs: Readonly<Record<string, string>> = {
  operations: "operations-center",
  medicine: "medicine-governance",
  stock: "stock-intelligence",
  procurement: "procurement",
  dispensing: "dispensing-sales",
  credit: "credit-management",
  recovery: "smart-credit-recovery",
  finance: "financial-control",
  analytics: "analytics-insights",
  insurance: "insurance-mutuelle",
  wholesale: "wholesale-management",
  quotation: "quotation-sales-orders",
  expiry: "expiry-disposal",
  declaration: "inventory-declaration",
  multisite: "multi-site-management",
  reports: "scheduled-email-reports",
  compliance: "compliance-audit",
  configuration: "system-configuration",
  remote: "web-remote-access",
};

export function productFeatureId(slug: string) {
  return Object.entries(productPageSlugs).find(([, productSlug]) => productSlug === slug)?.[0];
}

